using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace PZ3D {static class VersionPreserveNativeUi {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4194304};static readonly object Output=new object();static readonly ManualResetEventSlim Release=new ManualResetEventSlim();static string root,game,user,data,destination,scenario="normal";static bool held,altered;static ModernController controller;
 static void Send(object value){lock(Output){Console.WriteLine(Json.Serialize(value));Console.Out.Flush();}}static void Put(string p,string text){Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,text,new UTF8Encoding(false));}
 static object Files(){return new{destination=destination,targetExists=destination!=null&&Directory.Exists(destination),partials=Directory.GetDirectories(Path.Combine(root,"保存位置"),"*.partial-*").Length,registered=new VersionLibrary(data,game,user).ListReadOnly(out ignored).Where(v=>v.Managed).Select(v=>new{id=v.Id,path=v.GamePath,name=v.Name}).ToArray(),files=destination!=null&&Directory.Exists(destination)?Directory.GetFiles(destination,"*",SearchOption.AllDirectories).Select(p=>new{path=p,sha256=DlssInstaller.HashFile(p),length=new FileInfo(p).Length}).ToArray():new object[0]};}static string ignored;
 public static int Main(){try{Console.InputEncoding=new UTF8Encoding(false);Console.OutputEncoding=new UTF8Encoding(false);root=Path.Combine(Path.GetTempPath(),"版本界面-"+Guid.NewGuid().ToString("N"));game=Path.Combine(root,"原游戏");user=Path.Combine(root,"用户");data=Path.Combine(root,"数据");Put(Path.Combine(game,"ProjectZomboid64.exe"),"owned fixture; never execute");Put(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(game,"version.txt"),"42.21.0");Put(Path.Combine(game,"media","中文.bin"),new string('x',6*1024*1024));Put(Path.Combine(user,"mods","default.txt"),"unchanged user mod list");Directory.CreateDirectory(Path.Combine(root,"保存位置"));
 using(controller=new ModernController(game,user,data,true)){controller.Progress=(v,t)=>{Send(new{progress=true,value=v,text=t});string marker=scenario=="scan"?"正在核对原游戏":scenario=="copy"?"正在复制":scenario=="verifyCopy"?"正在校验副本":scenario=="verifySource"?"正在复核原游戏":null;if(!held&&marker!=null&&t.Contains(marker)){held=true;Send(new{holding=true,stage=scenario});if(!Release.Wait(20000))throw new TimeoutException("owned fixture hold timed out");}if(scenario=="failure"&&!altered&&t.Contains("正在复制")){altered=true;Put(Path.Combine(game,"Steam-update.bin"),"isolated source changed during copy");}};
 Send(new{ready=true,root=root,game=game,user=user,data=data});var jobs=new List<Task>();string line;while((line=Console.ReadLine())!=null){string captured=line;jobs.Add(Task.Run(()=>{object id=null;try{var raw=Json.Deserialize<Dictionary<string,object>>(captured);id=raw["id"];string action=(string)raw["action"];if(action=="fixtureScenario"){scenario=Convert.ToString(((Dictionary<string,object>)raw["payload"])["scenario"]);held=false;altered=false;Release.Reset();Send(new{id=id,ok=true,data=new{scenario=scenario}});return;}if(action=="fixtureRelease"){Release.Set();Send(new{id=id,ok=true,data=new{released=true}});return;}var request=ModernHostPolicy.Validate("https://orange.local/index.html",captured);var p=(Dictionary<string,object>)request["payload"];if(action=="versionChoosePreserve"){var selection=LibraryFolderSelection.Begin(action,p);p=selection.Select(Path.Combine(root,"保存位置"));destination=Convert.ToString(p["destination"]);action=selection.Action;}if(!new[]{"versionPreserve","versionList","versionInstallState","cancel","taskGet"}.Contains(action))throw new Exception("fixture action denied");if(action=="cancel"){controller.Cancel();Release.Set();}object result=controller.CaptureRequest(action,p)();Send(new{id=id,ok=true,data=result,files=Files()});}catch(Exception error){Send(new{id=id,ok=false,error=error.Message,files=Files()});}}));}Release.Set();Task.WaitAll(jobs.ToArray());}return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}}
